            "value": "(function execute(table) {\n    /* Code your glide record query logic here. For example:\n\n        var options = [];\n        var gr = new GlideRecordSecure(table);\n        gr.addEncodedQuery('active=true^numberSTARTSWITHINC001001');\n        gr.setLimit(10);\n        gr.query();\n        while(gr.next()) {\n            options.push({ 'value': gr.getUniqueValue(), 'label': gr.getValue('short_description') });\n        }\n        return options;\n    */\n     var gr = new GlideRecordSecure(table);\n     gr.addQuery('active', true); // Condition: Active = true\n    gr.query();\n\n    if (gr.next()) {\n        gForm.setValue('choice_field', gr.sys_id); // Replace 'choice_field' with actual field name\n    } else {\n        gForm.addInfoMessage(\"You have no open NeedIt records.\");\n    }\n\n    var options = []; // add options here...\n    return options;\n})(table)\n"
